import { NotFoundError } from '../../domain/errors/DomainErrors';
import { StockAllocation } from '../../domain/inventory/StockReservationService';
import { ProductRepository } from '../../domain/product/ProductRepository';
import { Quantity } from '../../domain/shared/Quantity';

export interface ProductQuantity {
  readonly productId: string;
  readonly quantity: Quantity;
}

/** Loads the products behind a set of order lines and persists them after stock has moved. */
export class StockAllocationService {
  constructor(private readonly products: ProductRepository) {}

  load(items: readonly ProductQuantity[]): StockAllocation[] {
    return items.map(({ productId, quantity }) => {
      const product = this.products.findById(productId);
      if (!product) {
        throw new NotFoundError('Product', productId);
      }
      return { product, quantity };
    });
  }

  persist(allocations: readonly StockAllocation[]): void {
    for (const { product } of allocations) {
      this.products.save(product);
    }
  }
}

=====SOURCE-END=====

